96	/** What the map needs beyond the world it draws. */
97	interface SurfaceProps {
98	  /** The world to draw. */
99	  readonly world: WorldView;
100	  /** What the panel beside the map is open on. */
101	  readonly selection: Selection;
102	  /** Called when the reader selects a claim or an arrow, by pointer or by keyboard. */
103	  readonly onSelect: (selection: Selection) => void;
104	  /** Which claim the keyboard is on. Held outside the map, because the keys are. */
105	  readonly focused: string | null;
106	  /** Put the keyboard on a claim. */
107	  readonly onFocused: (id: string | null) => void;
108	  /**
109	   * How tall to draw each tile, when a diff needs one box to hold two paintings.
110	   * Left out, each tile is as tall as its own content.
111	   */
112	  readonly heights?: ReadonlyMap<string, number>;
113	  /**
114	   * Which map this is: the base map, or the base map with one branch folded on.
115	   *
116	   * Both paintings of one diff share it, so flipping between them moves nothing.
117	   * Opening a different branch changes it, and the union of the two worlds is
118	   * then laid out again from scratch — one layout, two paintings.
119	   */
120	  readonly mapKey: string;
121	  /** Everything the keys that are not about moving are wired to. */
122	  readonly keys: MapKeys;
123	  /** Say what the last keystroke did, under the map. */
124	  readonly onStatus: (line: string) => void;
125	  /**
126	   * The reader asked to see the claims a column had no room for.
127	   *
128	   * The collapsed tile does not expand: it opens the outline, filtered to that
129	   * column. The outline is built from the world rather than from what is
130	   * painted, so those claims already have items there and the tile only has to
131	   * point at them.
132	   */
133	  readonly onOverflow: (column: { layer: number; claims: readonly string[] }) => void;
134	  /**
135	   * True while the map is arriving, which is when the one animation it spends on
136	   * causality runs: the wires draw in the order the argument runs, a column at a
137	   * time. Under reduced motion the ordering survives and the drawing goes.
138	   */
139	  readonly arriving: boolean;
140	  /**
141	   * The rectangles the map is holding open at its growing edge, while a map is
142	   * still being built.
143	   *
144	   * Empty on every finished map, which is every map this canvas drew before
145	   * generation existed — so nothing about a stored example changes.
146	   */
147	  readonly reserved?: readonly ReservedBox[];
148	  /**
149	   * What the canvas says about the session it is in, such as that this run is a
150	   * recording being played back. Drawn in the corner of the surface, over
151	   * nothing.
152	   */
153	  readonly badge?: ReactNode;
154	  /**
155	   * A word that changes when the map should be framed again.
156	   *
157	   * The map is framed once, when it is first drawn, and never again — losing
158	   * your place because the map was rearranged is the most disorienting thing a
159	   * canvas can do. A map that **builds itself** has one more moment worth
160	   * framing: the one where it stops. Nothing on it moves then, the reader is
161	   * about to start reading, and a four-column map framed for its first single
162	   * rectangle is a map they would otherwise have to hunt around.
163	   *
164	   * It is a word rather than a flag so that the effect has something to compare:
165	   * the map is framed once for each value it has ever had.
166	   */
167	  readonly frameAgainOn?: string;
168	}
