170	/** The surface itself. Lives inside the provider so it can move the view. */
171	function MapSurface({
172	  world,
173	  selection,
174	  onSelect,
175	  focused,
176	  onFocused,
177	  heights,
178	  mapKey,
179	  keys,
180	  onStatus,
181	  onOverflow,
182	  arriving,
183	  reserved,
184	  badge,
185	  frameAgainOn,
186	}: SurfaceProps) {
187	  const flow = useReactFlow();
188	  const surface = useRef<HTMLDivElement>(null);
189	  const [pointingAt, setPointingAt] = useState<string | null>(null);
190	
191	  const drawing = useMemo(() => toFlow(world, heights, reserved), [world, heights, reserved]);
192	  const layout = useLayout(drawing.tiles, drawing.layoutEdges, mapKey);
193	
194	  // How far the map is zoomed out. Below the threshold a wire's plate would
195	  // have its words drawn under eleven pixels on the glass, which is the one
196	  // thing nothing in this product is allowed to do, so the plates go and the
197	  // stroke keeps saying what kind of push each wire is.
198	  const zoom = useStore((state) => state.transform[2]);
199	  const tooSmallForWords = zoom < SUMMARY_BELOW_ZOOM;
200	
201	  /** How tall a tile turned out to be, so the view can be centred on its middle. */
202	  const heightOf = useCallback(
203	    (id: string) => drawing.tiles.find((tile) => tile.id === id)?.height ?? 0,
204	    [drawing],
205	  );
206	
207	  /** Where every tile ended up, which is what routing a wire needs to know. */
208	  const boxes = useMemo(() => {
209	    const placed = new Map<string, Box>();
210	    for (const [id, at] of layout.positions) {
211	      placed.set(id, { x: at.x, y: at.y, width: TILE_WIDTH, height: heightOf(id) });
212	    }
213	    return placed;
214	  }, [layout, heightOf]);
215	
216	  // What the hover lens leaves lit. `null` is everything, which is what the map
217	  // looks like when the reader is not pointing at anything. The claim the
218	  // keyboard is on counts as being pointed at, so the lens is not a mouse-only
219	  // feature.
220	  const lens = useMemo(() => {
221	    // **The lens only ever reads a claim that is on the map.** A box can leave
222	    // under the pointer — a reserved rectangle becomes a tile, a claim is
223	    // dropped by a branch — and the mouse never leaves it, because there is
224	    // nothing left to leave. What was pointed at is then a name the map does not
225	    // hold, nothing is on its path, and the whole map dims to fifteen per cent
226	    // with nothing lit. That is the lens answering a question about something
227	    // that is not there.
228	    const under = world.claims.some((claim) => claim.id === pointingAt) ? pointingAt : null;
229	    // **While a map is still arriving the lens is off unless the reader points
230	    // at something.** Focus moves by itself on a map that is building — every
231	    // claim that arrives takes it, so the view can follow the growing edge — and
232	    // dimming the rest of the map because the machine moved is the lens
233	    // answering a question nobody asked. Pointing at a tile still works.
234	    return onThePathFrom(under ?? (arriving ? null : focused), world.links);
235	  }, [pointingAt, focused, world.claims, world.links, arriving]);
236	
237	  // Which column each claim sits in, for the one animation this map spends on
238	  // causality: the wires arrive in the order the argument runs, a column at a
239	  // time. The order is read from the map's own shape, never from the clock.
240	  const column = useMemo(() => {
241	    const placed = new Map<string, number>();
242	    for (const one of assignLayers(
243	      world.claims.map((claim) => claim.id),
244	      world.links,
245	    )) {
246	      placed.set(one.id, one.layer);
247	    }
248	    return placed;
249	  }, [world]);
250	
251	  const nodes: MapNode[] = useMemo(
252	    () =>
253	      drawing.nodes.map((node) => {
254	        const ghost = node.type === "claim" && node.data.claim.ghost === true;
255	        return {
256	          ...node,
257	          position: layout.positions.get(node.id) ?? { x: 0, y: 0 },
258	          selected: selection?.kind === "claim" && selection.id === node.id,
259	          // Two classes and not one: the hover lens and the other world are both
260	          // opacity, and a tile that is off the hovered path *and* in the other
261	          // world has to land at the two multiplied together rather than at
262	          // whichever rule happened to win. `canvas.css` multiplies them.
263	          className: [
264	            // A rectangle held open for a claim that has not arrived is never
265	            // dimmed by the lens. The lens answers "what does this have to do
266	            // with anything", and a box standing for a claim that does not exist
267	            // yet is not on anybody's path — dimming it would hide the one thing
268	            // a reader watching a map build itself is waiting for.
269	            lens !== null && !lens.claims.has(node.id) && !node.id.startsWith(RESERVED_PREFIX)
270	              ? "is-dimmed"
271	              : "",
272	            ghost ? "is-ghost" : "",
273	          ]
274	            .filter((one) => one !== "")
275	            .join(" "),
276	        };
277	      }),
278	    [drawing, layout, lens, selection],
279	  );
280	
281	  const edges: MapEdge[] = useMemo(() => {
282	    const routable = drawing.edges.map((edge) => ({
283	      id: edge.id,
284	      source: edge.source,
285	      target: edge.target,
286	      handle: edge.sourceHandle ?? "out-trigger",
287	      reflexive: edge.data?.reflexive === true,
288	      mode: edge.data?.mode ?? "trigger",
289	      strength: edge.data?.strength ?? 0,
290	      lag: edge.data?.lag ?? 0,
291	    }));
292	    const plans = planRoutes(routable, boxes);
293	    const offsets = tailOffsets(routable);
294	    // Where every plate goes, worked out for the whole map at once. A wire
295	    // cannot see its neighbours, and once two worlds are laid over each other
296	    // that is not enough: the union crowds the middle of the map and plates
297	    // began landing on one another.
298	    const plates = planPlates({ wires: routable, boxes, plans, tailOffsets: offsets });
299	    const wires = new Map(world.links.map((link) => [link.id, link]));
300	    return drawing.edges.map((edge) => {
301	      if (edge.data === undefined) {
302	        return edge;
303	      }
304	      const wire = wires.get(edge.id);
305	      return {
306	        ...edge,
307	        selected: selection?.kind === "wire" && selection.id === edge.id,
308	        // The wave's place in the order, and whether this wire belongs to the
309	        // world you are not looking at. Both are carried as classes, because a
310	        // class is what the drawing library puts on the group the wire is drawn
311	        // in, and a wire cannot know where the other wires are.
312	        className: [
313	          `wave-${Math.min(column.get(edge.source) ?? 0, 5)}`,
314	          wire?.ghost === true ? "is-ghost" : "",
315	          wire?.change === undefined ? "" : `is-${wire.change}`,
316	        ]
317	          .filter((one) => one !== "")
318	          .join(" "),
319	        data: {
320	          ...edge.data,
321	          plan: plans.get(edge.id),
322	          tailOffset: offsets.get(edge.id),
323	          plateAt: plates.get(edge.id),
324	          wave: Math.min(column.get(edge.source) ?? 0, 5),
325	          dimmed: lens !== null && !lens.wires.has(edge.id),
326	          tooSmallForWords,
327	        },
328	      };
329	    });
330	  }, [drawing, boxes, lens, selection, tooSmallForWords, world, column]);
331	
332	  /**
333	   * Everything the first frame has to hold: every tile, and the strip of empty
334	   * space above them that the one backwards wire runs along.
335	   */
336	  const mapBounds = useCallback(() => {
337	    const placed = [...layout.positions.entries()];
338	    if (placed.length === 0) {
339	      return null;
340	    }
341	    const left = Math.min(...placed.map(([, at]) => at.x));
342	    const right = Math.max(...placed.map(([, at]) => at.x)) + TILE_WIDTH;
343	    const top = Math.min(...placed.map(([, at]) => at.y));
344	    const bottom = Math.max(...placed.map(([id, at]) => at.y + heightOf(id)));
345	    const overhead = drawing.edges.some((edge) => edge.data?.reflexive === true) ? SKY_GAP + 8 : 0;
346	    return { x: left, y: top - overhead, width: right - left, height: bottom - top + overhead };
347	  }, [drawing, layout, heightOf]);
348	
349	  const framed = useRef<string | null>(null);
350	  const justFramed = useRef(false);
