        data: {
          ...edge.data,
          plan: plans.get(edge.id),
          tailOffset: offsets.get(edge.id),
          plateAt: plates.get(edge.id),
          wave: Math.min(column.get(edge.source) ?? 0, 5),
          dimmed: lens !== null && !lens.wires.has(edge.id),
