import { chromium } from "/Users/kentgang/git3/katalyst-wt/feat-04a-growth/frontend/node_modules/playwright-core/index.mjs";

export const APP = "http://localhost:5148/";
export const SENTENCE = "The Strait of Hormuz is going to open next week.";

export async function open({ theme = "dark", motion = "no-preference", cpu = 1 } = {}) {
  const browser = await chromium.launch();
  const context = await browser.newContext({
    viewport: { width: 1600, height: 1000 },
    colorScheme: theme,
    reducedMotion: motion === "reduce" ? "reduce" : "no-preference",
  });
  const page = await context.newPage();
  const loops = [];
  const console_ = [];
  page.on("console", (m) => {
    console_.push(`${m.type()}: ${m.text()}`);
  });
  page.on("pageerror", (e) => {
    console_.push(`pageerror: ${e.message}`);
  });
  // ResizeObserver loop errors surface as window "error" events, which Playwright
  // reports via pageerror only sometimes; catch them explicitly too.
  await page.addInitScript(() => {
    window.__loops = [];
    window.addEventListener("error", (e) => {
      window.__loops.push(String(e.message));
    });
  });
  if (cpu !== 1) {
    const cdp = await context.newCDPSession(page);
    await cdp.send("Emulation.setCPUThrottlingRate", { rate: cpu });
  }
  return { browser, context, page, console_, loops };
}

export async function loopErrors(page) {
  return await page.evaluate(() => window.__loops ?? []);
}

