import { open, APP, SENTENCE } from "./lib.mjs";
import { readFileSync } from "node:fs";

// N = how many wire blocks to let through before the body simply ends.
const N = Number(process.argv[2] ?? 0);
const pretendKey = process.argv[3] === "key";
const shot = process.argv[4];

const whole = readFileSync(
  "/private/tmp/claude-501/-Users-kentgang-git3-katalyst/ef0fe818-4a51-417f-a20d-5479dc442258/scratchpad/review-growth-2/stream.txt",
  "utf8",
);
const blocks = whole.split(/\n\n/).filter((b) => b.trim() !== "");
const body = blocks.slice(0, N).map((b) => `${b}\n\n`).join("");

const { browser, page, console_ } = await open();
const posts = [];
page.on("request", (r) => {
  if (r.method() === "POST" && r.url().includes("/api/generate")) posts.push(Date.now());
});

if (pretendKey) {
  await page.route("**/api/readyz", async (route) => {
    const answer = await route.fetch();
    const said = await answer.json();
    await route.fulfill({ json: { ...said, model_key_present: true } });
  });
}

await page.route("**/api/generate", async (route) => {
  await route.fulfill({
    status: 200,
    headers: { "content-type": "text/event-stream", "cache-control": "no-cache" },
    body,
  });
});

await page.goto(APP);
await page.locator(".launchpad").first().waitFor();
if (pretendKey) {
  // With a key the cards run live; press the first card all the same.
}
const card = page
  .getByRole("button", { name: new RegExp(SENTENCE.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")) })
  .first();
await card.click();
await page.waitForTimeout(1500);

const state = await page.evaluate(() => {
  const q = (s) => document.querySelector(s);
  return {
    doneKind: q(".done-line")?.dataset.kind ?? null,
    doneText: (q(".done-line")?.textContent ?? "").trim(),
    again: (q(".done-line__again")?.textContent ?? "").trim(),
    tiles: document.querySelectorAll(".tile").length,
    nodes: document.querySelectorAll(".react-flow__node").length,
    skeletons: document.querySelectorAll(".skeleton-tile").length,
    receipt: document.querySelectorAll(".receipt-strip").length,
    addAClaim: document.querySelectorAll(".add-a-claim").length,
    refusalStrip: document.querySelectorAll(".refusal-strip").length,
    title: (q(".map-bar__title")?.textContent ?? "").trim(),
    origin: [...document.querySelectorAll(".map-origin__line")].map((p) => p.textContent.trim()),
    panelText: (q(".dock")?.textContent ?? "").trim().slice(0, 400),
    loops: window.__loops ?? [],
  };
});
console.log(JSON.stringify({ N, pretendKey, posts: posts.length, ...state }, null, 1));

if (shot) {
  await page.screenshot({ path: shot, fullPage: false });
}

// Press run-again twice, fast, and count the requests that follow.
const before = posts.length;
const again = page.locator(".done-line__again");
if ((await again.count()) > 0) {
  await again.click({ clickCount: 2, delay: 15 });
  await page.waitForTimeout(1500);
  console.log("after pressing run-again twice quickly, extra POSTs:", posts.length - before);
  console.log(
    "screen now:",
    await page.evaluate(() => ({
      doneKind: document.querySelector(".done-line")?.dataset.kind ?? null,
      agains: document.querySelectorAll(".done-line__again").length,
    })),
  );
}
console.log("console:", console_.filter((l) => /error|warn|pageerror/i.test(l)).slice(0, 10));
await browser.close();

