import { open, APP, SENTENCE } from "./lib.mjs";
import { readFileSync } from "node:fs";

const mode = process.argv[2] ?? "dbl"; // dbl | two | slow
const whole = readFileSync(
  "/private/tmp/claude-501/-Users-kentgang-git3-katalyst/ef0fe818-4a51-417f-a20d-5479dc442258/scratchpad/review-growth-2/stream.txt",
  "utf8",
);
const blocks = whole.split(/\n\n/).filter((b) => b.trim() !== "");
const body = blocks.slice(0, 6).map((b) => `${b}\n\n`).join("");

const { browser, page } = await open();
const posts = [];
const t0 = Date.now();
page.on("request", (r) => {
  if (r.method() === "POST" && r.url().includes("/api/generate")) posts.push(Date.now() - t0);
});

await page.route("**/api/generate", async (route) => {
  await route.fulfill({
    status: 200,
    headers: { "content-type": "text/event-stream" },
    body,
  });
});

await page.goto(APP);
const card = page
  .getByRole("button", { name: new RegExp(SENTENCE.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")) })
  .first();
await card.click();
await page.locator(".done-line__again").waitFor();
console.log("posts after the first press:", posts.length);

const box = await page.locator(".done-line__again").boundingBox();
const at = { x: box.x + box.width / 2, y: box.y + box.height / 2 };
const before = posts.length;

if (mode === "dbl") {
  await page.mouse.dblclick(at.x, at.y);
} else if (mode === "two") {
  await page.mouse.click(at.x, at.y);
  await page.mouse.click(at.x, at.y);
} else {
  await page.mouse.click(at.x, at.y);
  await page.waitForTimeout(400);
  const again = page.locator(".done-line__again");
  if ((await again.count()) > 0) await again.click();
}

await page.waitForTimeout(2000);
console.log(mode, "extra POSTs:", posts.length - before, "times:", posts);
console.log(
  "what is under that point now:",
  await page.evaluate(
    ([x, y]) => {
      const el = document.elementFromPoint(x, y);
      return el ? `${el.tagName}.${el.className}` : null;
    },
    [at.x, at.y],
  ),
);
await browser.close();

