import { open, APP, SENTENCE } from "./lib.mjs";

const { browser, page, console_ } = await open();
const net = [];
const t0 = Date.now();
page.on("request", (r) => {
  if (r.url().includes("/api/")) net.push([Date.now() - t0, "req", r.method(), r.url()]);
});
page.on("requestfinished", (r) => {
  if (r.url().includes("/api/generate") && r.method() === "POST")
    net.push([Date.now() - t0, "finished", r.url()]);
});
page.on("requestfailed", (r) => {
  if (r.url().includes("/api/generate") && r.method() === "POST")
    net.push([Date.now() - t0, "failed", r.failure()?.errorText]);
});

await page.goto(APP);
await page
  .getByRole("button", { name: new RegExp(SENTENCE.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")) })
  .first()
  .click();
// Mid-run: a few tiles in, nothing finished.
await page.locator(".tile").first().waitFor();
await page.waitForTimeout(2500);
const midway = await page.evaluate(() => document.querySelectorAll(".tile").length);
console.log("tiles when leaving:", midway, "at", Date.now() - t0, "ms");
await page.getByRole("button", { name: /Back to the launchpad/ }).click();
await page.waitForTimeout(6000);
console.log("network:", net);
console.log("on the launchpad:", await page.locator(".launchpad").count());
console.log("console:", console_.filter((l) => /error|warn|pageerror/i.test(l)).slice(0, 10));
await browser.close();

