import { open, APP, SENTENCE } from "./lib.mjs";
import { readFileSync } from "node:fs";

const mode = process.argv[2] ?? "real"; // real | drafted | badjson | 500 | reject | refused
const shot = process.argv[3];

const { browser, page, console_ } = await open();
let sentBody = null;
page.on("request", (r) => {
  if (r.url().includes("/api/generate/insert")) sentBody = r.postData();
});

// Play the whole recording fast by letting it through, but stub the insert.
if (mode !== "real") {
  await page.route("**/api/generate/insert", async (route) => {
    if (mode === "badjson") {
      await route.fulfill({ status: 200, contentType: "text/html", body: "<html>hello</html>" });
    } else if (mode === "500") {
      await route.fulfill({ status: 500, contentType: "application/json", body: '{"detail":"the server broke while drafting this claim."}' });
    } else if (mode === "reject") {
      await route.abort("failed");
    } else if (mode === "refused") {
      await route.fulfill({
        status: 422,
        contentType: "application/json",
        body: JSON.stringify({
          detail: [
            { code: "cycle", message: 'These claims form a loop with no delay in it: "A" → "B" → "A". Mark the arrow where a market feeds back on the world as reflexive and give it a delay, or remove one arrow.' },
            { code: "unjudgeable", message: 'Nothing says how "a hurricane closes the Gulf" would be settled, so nobody could score it.' },
          ],
        }),
      });
    } else {
      // A DraftedInsert: the edit, its receipt, and its working.
      const insert = JSON.parse(readFileSync(new URL("./drafted.json", import.meta.url), "utf8"));
      await route.fulfill({ status: 200, contentType: "application/json", body: JSON.stringify(insert) });
    }
  });
}

await page.goto(APP);
await page
  .getByRole("button", { name: new RegExp(SENTENCE.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")) })
  .first()
  .click();
await page.locator(".receipt-strip").first().waitFor({ timeout: 120000 });
await page.locator(".done-line").waitFor();

const before = await page.evaluate(() => ({
  addAClaim: document.querySelectorAll(".add-a-claim").length,
}));
console.log("before typing:", before);

const field = page.getByLabel("…but this also happens");
await field.fill("…but a hurricane closes the Gulf");
await page.getByRole("button", { name: "Draft this claim" }).click();
await page.waitForTimeout(3000);

const after = await page.evaluate(() => {
  const q = (s) => document.querySelector(s);
  const ask = q(".add-a-claim__ask");
  return {
    answer: q("[data-answer]")?.dataset.answer ?? null,
    answerText: (q("[data-answer]")?.textContent ?? "").trim().slice(0, 600),
    askLabel: (ask?.textContent ?? "").trim(),
    askDisabled: ask?.disabled ?? null,
    receipts: document.querySelectorAll(".receipt-strip").length,
    receiptHeadings: [...document.querySelectorAll(".receipt-strip__heading")].map((h) => h.textContent),
    workings: document.querySelectorAll(".inspector__transcript").length,
    header: document.querySelectorAll(".map-bar").length,
    loops: window.__loops ?? [],
  };
});
console.log(JSON.stringify({ mode, sentBody, ...after }, null, 1));
if (shot) await page.screenshot({ path: shot });
console.log("console:", console_.filter((l) => /error|warn|pageerror/i.test(l)).slice(0, 6));
await browser.close();

