import { open, APP, SENTENCE } from "./lib.mjs";

const cpu = Number(process.argv[2] ?? 1);
const theme = process.argv[3] ?? "dark";
const prefix = process.argv[4] ?? "watch";

const { browser, page, console_ } = await open({ cpu, theme });

await page.goto(APP);
await page.locator(".launchpad").first().waitFor();
await page.screenshot({ path: `${prefix}-00-launchpad.png` });

// Watch every frame of the growing map: which boxes are on screen, whether any
// of them is invisible, whether any two overlap, and where each one sits.
await page.evaluate(() => {
  window.__seen = [];
  const look = () => {
    const boxes = [...document.querySelectorAll(".react-flow__node")].map((box) => {
      const style = getComputedStyle(box);
      const at = box.getBoundingClientRect();
      return {
        id: box.dataset.id,
        hidden:
          style.visibility === "hidden" ||
          style.display === "none" ||
          Number(style.opacity) === 0,
        x: Math.round(at.x),
        y: Math.round(at.y),
        w: Math.round(at.width),
        h: Math.round(at.height),
      };
    });
    const overlaps = [];
    for (let i = 0; i < boxes.length; i += 1) {
      for (let j = i + 1; j < boxes.length; j += 1) {
        const a = boxes[i];
        const b = boxes[j];
        if (a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h) {
          overlaps.push(`${a.id} ∩ ${b.id}`);
        }
      }
    }
    window.__seen.push({
      t: Math.round(performance.now()),
      tiles: document.querySelectorAll(".tile").length,
      skeletons: document.querySelectorAll(".skeleton-tile").length,
      wires: document.querySelectorAll(".react-flow__edge").length,
      hidden: boxes.filter((b) => b.hidden).map((b) => b.id),
      overlaps,
      boxes,
    });
  };
  const watching = new MutationObserver(look);
  watching.observe(document.body, { subtree: true, childList: true, attributes: true });
  window.__stop = () => watching.disconnect();
  look();
});

await page
  .getByRole("button", { name: new RegExp(SENTENCE.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")) })
  .first()
  .click();

await page.locator(".skeleton-tile").first().waitFor();
await page.screenshot({ path: `${prefix}-01-first-rectangle.png` });
await page.waitForFunction(() => document.querySelectorAll(".tile").length >= 3, null, {
  timeout: 180000,
});
await page.screenshot({ path: `${prefix}-02-mid-growth.png` });
await page.locator(".receipt-strip").first().waitFor({ timeout: 300000 });
await page.locator(".done-line").waitFor();
await page.waitForTimeout(1500);
await page.screenshot({ path: `${prefix}-03-finished.png` });

const seen = await page.evaluate(() => {
  window.__stop?.();
  return window.__seen;
});

// What moved: a box that was placed and then sat somewhere else.
const placed = new Map();
const moved = [];
const everHidden = new Set();
const everOverlapped = new Set();
for (const frame of seen) {
  for (const id of frame.hidden) everHidden.add(id);
  for (const o of frame.overlaps) everOverlapped.add(o);
  for (const box of frame.boxes) {
    // Only compare within one framing: the map is deliberately re-framed when the
    // run stops, which moves every box on the glass at once.
    const was = placed.get(box.id);
    if (was === undefined) placed.set(box.id, box);
    else if (was.x !== box.x || was.y !== box.y) moved.push({ id: box.id, was, now: box });
  }
}

// Where each box sat in the map's own coordinates, so that a whole-map re-frame
// is not read as a tile moving.
const relative = [];
for (const frame of seen) {
  const first = frame.boxes[0];
  if (first === undefined) continue;
  relative.push({
    t: frame.t,
    tiles: frame.tiles,
    rel: frame.boxes.map((b) => `${b.id}@${b.x - first.x},${b.y - first.y},${b.w}x${b.h}`).join(" | "),
  });
}
const relMoved = [];
const relSeen = new Map();
for (const frame of relative) {
  for (const one of frame.rel.split(" | ")) {
    const id = one.split("@")[0];
    const was = relSeen.get(id);
    if (was === undefined) relSeen.set(id, one);
    else if (was !== one) relMoved.push(`${was}  ->  ${one} at ${frame.t}`);
  }
}

const loops = await page.evaluate(() => window.__loops ?? []);
console.log(
  JSON.stringify(
    {
      cpu,
      theme,
      frames: seen.length,
      tilesWent: [...new Set(seen.map((f) => f.tiles))],
      skeletonsWent: [...new Set(seen.map((f) => f.skeletons))],
      everHidden: [...everHidden],
      everOverlapped: [...everOverlapped],
      absoluteMoves: moved.length,
      relativeMoves: relMoved.slice(0, 12),
      relativeMoveCount: relMoved.length,
      loops,
      consoleErrors: console_.filter((l) => /error|warn|pageerror|ResizeObserver/i.test(l)).slice(0, 12),
    },
    null,
    1,
  ),
);
await browser.close();

