import { open, APP, SENTENCE } from "./lib.mjs";
import { writeFileSync } from "node:fs";

const cpu = Number(process.argv[2] ?? 1);
const prefix = process.argv[3] ?? "w2";

const { browser, page, console_ } = await open({ cpu });
await page.goto(APP);
await page.locator(".launchpad").first().waitFor();

await page.evaluate(() => {
  window.__seen = [];
  const look = () => {
    const boxes = [...document.querySelectorAll(".react-flow__node")].map((box) => {
      const style = getComputedStyle(box);
      // React Flow puts each node at its map coordinate with its own transform.
      const t = style.transform;
      const m = /matrix\(([^)]+)\)/.exec(t);
      const parts = m ? m[1].split(",").map(Number) : null;
      return {
        id: box.dataset.id,
        // The map's own coordinates, straight off the node's transform.
        mx: parts ? Math.round(parts[4]) : null,
        my: parts ? Math.round(parts[5]) : null,
        w: Math.round(box.getBoundingClientRect().width),
        h: Math.round(box.getBoundingClientRect().height),
        vis: style.visibility,
        disp: style.display,
        op: style.opacity,
        onGlass: (() => {
          const at = box.getBoundingClientRect();
          return at.width > 0 && at.height > 0;
        })(),
      };
    });
    window.__seen.push({
      t: Math.round(performance.now()),
      tiles: document.querySelectorAll(".tile").length,
      skeletons: document.querySelectorAll(".skeleton-tile").length,
      boxes,
    });
  };
  const watching = new MutationObserver(look);
  watching.observe(document.body, { subtree: true, childList: true, attributes: true });
  window.__stop = () => watching.disconnect();
  look();
});

await page
  .getByRole("button", { name: new RegExp(SENTENCE.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")) })
  .first()
  .click();
await page.locator(".receipt-strip").first().waitFor({ timeout: 300000 });
await page.locator(".done-line").waitFor();
await page.waitForTimeout(1500);

const seen = await page.evaluate(() => {
  window.__stop?.();
  return window.__seen;
});
writeFileSync(`${prefix}-frames.json`, JSON.stringify(seen));

const firstAt = new Map();
const movedInMapCoords = [];
const hiddenSpells = [];
const overlapFrames = [];
for (const frame of seen) {
  for (const b of frame.boxes) {
    if (b.vis === "hidden" || b.disp === "none" || Number(b.op) === 0 || !b.onGlass) {
      hiddenSpells.push({ t: frame.t, id: b.id, vis: b.vis, disp: b.disp, op: b.op, w: b.w, h: b.h });
    }
    const key = b.id;
    const now = `${b.mx},${b.my}`;
    if (!firstAt.has(key)) firstAt.set(key, { at: now, t: frame.t });
    else if (firstAt.get(key).at !== now)
      movedInMapCoords.push({ id: key, from: firstAt.get(key).at, to: now, t: frame.t });
  }
  const bs = frame.boxes;
  const hits = [];
  for (let i = 0; i < bs.length; i += 1)
    for (let j = i + 1; j < bs.length; j += 1) {
      const a = bs[i];
      const b = bs[j];
      if (a.mx === null || b.mx === null) continue;
      if (a.mx < b.mx + b.w && b.mx < a.mx + a.w && a.my < b.my + b.h && b.my < a.my + a.h)
        hits.push(`${a.id}@${a.mx},${a.my} ∩ ${b.id}@${b.mx},${b.my}`);
    }
  if (hits.length > 0) overlapFrames.push({ t: frame.t, tiles: frame.tiles, hits });
}

console.log(
  JSON.stringify(
    {
      cpu,
      frames: seen.length,
      hiddenSpells: hiddenSpells.slice(0, 20),
      hiddenCount: hiddenSpells.length,
      movedInMapCoords: movedInMapCoords.slice(0, 20),
      movedCount: movedInMapCoords.length,
      overlapFrameCount: overlapFrames.length,
      firstOverlaps: overlapFrames.slice(0, 5),
      lastOverlap: overlapFrames[overlapFrames.length - 1],
      overlapSpanMs:
        overlapFrames.length > 0
          ? overlapFrames[overlapFrames.length - 1].t - overlapFrames[0].t
          : 0,
      loops: await page.evaluate(() => window.__loops ?? []),
      consoleErrors: console_.filter((l) => /error|pageerror|ResizeObserver/i.test(l)).slice(0, 8),
    },
    null,
    1,
  ),
);
await browser.close();

