import { open, APP, SENTENCE } from "./lib.mjs";

const theme = process.argv[2] ?? "dark";
const p = `sw-${theme}`;
const { browser, page, console_ } = await open({ theme });
const notes = [];
const shot = async (name) => {
  await page.screenshot({ path: `${p}-${name}.png` });
  notes.push([name, (await page.evaluate(() => window.__loops ?? [])).length]);
};

await page.goto(APP);
await page.locator(".launchpad").first().waitFor();
await shot("01-launchpad");

// The stored example: the other map screen, with the panel, the rail and the
// branch machinery on it.
await page.getByRole("button", { name: /Open the stored example|Strait of Hormuz/ }).first().click();
await page.waitForTimeout(2500);
await shot("02-stored-map");

// Every key.
await page.keyboard.press("?");
await page.waitForTimeout(600);
await shot("03-shortcuts");
await page.keyboard.press("Escape");

// The outline, in place of the panel.
await page.keyboard.press("o");
await page.waitForTimeout(500);
await shot("04-outline");
await page.keyboard.press("o");

// The command palette.
await page.keyboard.press("Control+k");
await page.waitForTimeout(500);
await shot("05-palette");
await page.keyboard.press("Escape");

// Squeeze the window so the panel and the stage both hold more than they show.
await page.setViewportSize({ width: 900, height: 620 });
await page.waitForTimeout(1200);
await shot("06-squeezed");
await page.setViewportSize({ width: 1600, height: 1000 });
await page.waitForTimeout(1200);

// Back, and then the growing map.
await page.getByRole("button", { name: /Back to the launchpad/ }).click();
await page.waitForTimeout(500);
await page
  .getByRole("button", { name: new RegExp(SENTENCE.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")) })
  .first()
  .click();
await page.waitForTimeout(2500);
await shot("07-growing");
await page.locator(".receipt-strip").first().waitFor({ timeout: 300000 });
await page.locator(".done-line").waitFor();
await page.waitForTimeout(1500);
await shot("08-finished");

// The working of the run, opened from the strip.
await page.getByRole("button", { name: /Read the working of this run/ }).click();
await page.waitForTimeout(800);
await shot("09-working");

// The panel scrolled to the bottom, where the rules say there is more above.
await page.locator(".dock").evaluate((it) => it.scrollTo(0, it.scrollHeight));
await page.waitForTimeout(600);
await shot("10-panel-bottom");

// A claim selected.
await page.locator(".tile").first().click();
await page.waitForTimeout(600);
await shot("11-claim");

// Squeeze the finished map too.
await page.setViewportSize({ width: 900, height: 620 });
await page.waitForTimeout(1200);
await shot("12-squeezed-map");
await page.setViewportSize({ width: 1600, height: 1000 });
await page.waitForTimeout(1000);

console.log("loops after each step:", JSON.stringify(notes));
console.log("all window errors:", await page.evaluate(() => window.__loops ?? []));
console.log(
  "console errors:",
  console_.filter((l) => /error|pageerror|ResizeObserver/i.test(l)).slice(0, 12),
);
await browser.close();

