import { open, APP, SENTENCE } from "./lib.mjs";

const theme = process.argv[2] ?? "dark";
const { browser, page, console_ } = await open({ theme });

const AUDIT = () => {
  const out = {
    tiny: [],
    clipped: [],
    identifiers: [],
    plurals: [],
    dialogs: document.querySelectorAll('[role="dialog"], dialog').length,
    progressbars: document.querySelectorAll('[role="progressbar"]').length,
    animated: [],
  };
  const ids = /\b01[0-9A-HJKMNP-TV-Z]{24}\b/g;
  for (const el of document.querySelectorAll("*")) {
    const style = getComputedStyle(el);
    if (style.visibility === "hidden" || style.display === "none") continue;
    const size = Number.parseFloat(style.fontSize);
    const own = [...el.childNodes]
      .filter((n) => n.nodeType === 3)
      .map((n) => n.textContent.trim())
      .join(" ")
      .trim();
    if (own !== "" && size < 11) {
      out.tiny.push({ cls: el.className?.toString?.().slice(0, 60), size, text: own.slice(0, 50) });
    }
    if (own !== "" && ids.test(own)) {
      out.identifiers.push({ cls: el.className?.toString?.().slice(0, 60), text: own.slice(0, 80) });
    }
    ids.lastIndex = 0;
    if (/\(s\)|\b1 \w+s\b/.test(own)) {
      out.plurals.push({ cls: el.className?.toString?.().slice(0, 60), text: own.slice(0, 60) });
    }
    // Text that its box cannot hold, so the reader sees part of a number.
    if (
      own !== "" &&
      el.scrollWidth > el.clientWidth + 1 &&
      style.overflow !== "visible" &&
      el.children.length === 0
    ) {
      out.clipped.push({
        cls: el.className?.toString?.().slice(0, 60),
        text: own.slice(0, 80),
        scroll: el.scrollWidth,
        client: el.clientWidth,
      });
    }
    if (style.animationName !== "none" && style.animationIterationCount !== "1") {
      out.animated.push({
        cls: el.className?.toString?.().slice(0, 60),
        name: style.animationName,
        count: style.animationIterationCount,
      });
    }
  }
  return out;
};

await page.goto(APP);
await page.locator(".launchpad").first().waitFor();
console.log("LAUNCHPAD", JSON.stringify(await page.evaluate(AUDIT), null, 1));

await page
  .getByRole("button", { name: new RegExp(SENTENCE.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")) })
  .first()
  .click();
await page.waitForTimeout(2200);
console.log("GROWING", JSON.stringify(await page.evaluate(AUDIT), null, 1));

await page.locator(".receipt-strip").first().waitFor({ timeout: 300000 });
await page.locator(".done-line").waitFor();
await page.waitForTimeout(1200);
console.log("FINISHED", JSON.stringify(await page.evaluate(AUDIT), null, 1));

await page.getByRole("button", { name: /Read the working of this run/ }).click();
await page.waitForTimeout(800);
const run = await page.evaluate(() => {
  const pairs = document.querySelector(".inspector__pairs--facts");
  const rows = pairs ? [...pairs.children].map((c) => c.textContent.trim()) : [];
  const monos = [...document.querySelectorAll(".inspector__mono")].map((m) => ({
    text: m.textContent,
    len: m.textContent.length,
    scroll: m.scrollWidth,
    client: m.clientWidth,
    wrap: getComputedStyle(m).overflowWrap + "/" + getComputedStyle(m).wordBreak,
  }));
  return { rows, monos };
});
console.log("RUN PANEL", JSON.stringify(run, null, 1));
console.log("WORKING AUDIT", JSON.stringify(await page.evaluate(AUDIT), null, 1));
console.log("console:", console_.filter((l) => /error|pageerror/i.test(l)).slice(0, 6));
await browser.close();

