import { open, APP } from "./lib.mjs";
import { readFileSync } from "node:fs";

const kind = process.argv[2] ?? "reached";
const theme = process.argv[3] ?? "dark";
const body = readFileSync(`verify-${kind}.sse`, "utf8");

const { browser, page, console_ } = await open({ theme });
await page.route("**/api/readyz", async (route) => {
  const answer = await route.fetch();
  await route.fulfill({ json: { ...(await answer.json()), model_key_present: true } });
});
await page.route("**/api/generate", async (route) => {
  await route.fulfill({ status: 200, headers: { "content-type": "text/event-stream" }, body });
});

await page.goto(APP);
await page.getByLabel("An event you think will happen").fill("The Strait of Hormuz is going to open next week.");
await page.getByLabel("Where you think it ends — optional").fill("A Polymarket contract on Brent below $70");
await page.getByRole("button", { name: "Build the map" }).click();
await page.locator(".done-line").waitFor({ timeout: 60000 });
await page.waitForTimeout(1200);
await page.screenshot({ path: `verify-${kind}-${theme}.png` });

const card = await page.evaluate(() => {
  const c = document.querySelector(".verdict-card");
  if (!c) return null;
  return {
    kind: c.dataset.kind,
    text: c.textContent,
    steps: [...c.querySelectorAll(".verdict-card__step")].map((s) => s.textContent),
    // every number anywhere in the card
    numbers: (c.textContent.match(/\d+(\.\d+)?/g) ?? []),
  };
});
const badge = await page.evaluate(() => ({
  replayBadges: document.querySelectorAll(".replay-badge").length,
  again: document.querySelectorAll(".done-line__again").length,
  receipt: [...document.querySelectorAll(".receipt-strip__line")].map(
    (l) => `${l.querySelector(".receipt-strip__label").textContent} = ${l.querySelector(".receipt-strip__reading").textContent}`,
  ),
}));
console.log(JSON.stringify({ kind, card, badge }, null, 1));
console.log("console:", console_.filter((l) => /error|pageerror/i.test(l)).slice(0, 6));
await browser.close();

