      n.getBoundingClientRect(),
    );
    const said = {
      left: canvas.dataset.moreLeft,
      right: canvas.dataset.moreRight,
      above: canvas.dataset.moreAbove,
      below: canvas.dataset.moreBelow,
    };
    const truly =
      boxes.length === 0
        ? null
        : {
            left: boxes.some((b) => b.left < room.left - 1) ? "yes" : "no",
