import { open, APP, SENTENCE } from "./lib.mjs";

const { browser, page, console_ } = await open({ motion: process.argv[2] ?? "no-preference" });
await page.goto(APP);

// The palette on the launchpad, and the step it takes.
await page.keyboard.press("Control+k");
await page.waitForTimeout(400);
console.log(
  "palette on the launchpad:",
  await page.evaluate(() => ({
    open: document.querySelectorAll(".palette").length,
    active: document.activeElement?.className ?? document.activeElement?.tagName,
  })),
);
await page.keyboard.press("Escape");

await page
  .getByRole("button", { name: new RegExp(SENTENCE.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")) })
  .first()
  .click();
await page.locator(".skeleton-tile").first().waitFor();

// While the map grows: put the keyboard somewhere that is not the map and watch.
await page.getByRole("button", { name: /Every key/ }).focus();
const watched = [];
for (let i = 0; i < 18; i += 1) {
  await page.waitForTimeout(400);
  watched.push(
    await page.evaluate(() => ({
      tiles: document.querySelectorAll(".tile").length,
      active: `${document.activeElement?.tagName}.${document.activeElement?.className}`.slice(0, 60),
    })),
  );
}
console.log("focus while the map grew:", JSON.stringify([...new Set(watched.map((w) => w.active))]));
console.log("tiles seen:", [...new Set(watched.map((w) => w.tiles))]);

await page.locator(".receipt-strip").first().waitFor({ timeout: 300000 });
await page.locator(".done-line").waitFor();
await page.waitForTimeout(1200);

// Every control on the finished screen, reachable by Tab.
const reachable = await page.evaluate(async () => {
  const seen = [];
  const all = [...document.querySelectorAll("button, a[href], input, select, textarea, [tabindex]")]
    .filter((el) => {
      const s = getComputedStyle(el);
      return s.visibility !== "hidden" && s.display !== "none" && !el.disabled && el.tabIndex >= 0;
    })
    .map((el) => `${el.tagName}.${(el.className || "").toString().split(" ")[0]}`);
  return [...new Set(all)];
});
console.log("focusable controls:", JSON.stringify(reachable, null, 1));

// Tab all the way round and see which of them the keyboard actually lands on.
const landed = new Set();
await page.getByRole("button", { name: /Back to the launchpad/ }).focus();
for (let i = 0; i < 60; i += 1) {
  await page.keyboard.press("Tab");
  landed.add(
    await page.evaluate(
      () => `${document.activeElement?.tagName}.${(document.activeElement?.className || "").toString().split(" ")[0]}`,
    ),
  );
}
console.log("landed on:", JSON.stringify([...landed], null, 1));

// The Add-a-claim field keeps the keyboard while things change beside it.
const field = page.getByLabel("…but this also happens");
await field.focus();
await field.type("…but a hurricane closes the Gulf", { delay: 10 });
await page.waitForTimeout(600);
