import { open, APP, SENTENCE } from "./lib.mjs";

const { browser, page, console_ } = await open();
await page.goto(APP);
await page.getByRole("button", { name: /Open the stored example|Strait of Hormuz/ }).first().click();
await page.waitForTimeout(2500);

const where = () =>
  page.evaluate(() => ({
    active: `${document.activeElement?.tagName}.${(document.activeElement?.className || "").toString().split(" ")[0]}`,
    open: document.querySelectorAll(".palette").length,
    picked: document.querySelector('.palette__command[aria-selected="true"], .palette__command[data-on="yes"]')?.textContent?.slice(0, 40) ?? null,
    commands: [...document.querySelectorAll(".palette__command")].map((c) => c.textContent.slice(0, 30)),
  }));

await page.keyboard.press("Control+k");
await page.waitForTimeout(400);
console.log("opened:", JSON.stringify(await where(), null, 1));

// The step: arrow keys walk the list, and the map must not take the keyboard back.
for (const key of ["ArrowDown", "ArrowDown", "ArrowUp"]) {
  await page.keyboard.press(key);
  await page.waitForTimeout(200);
  const w = await where();
  console.log(key, "->", w.active, "picked:", w.picked);
}
await page.keyboard.type("branch");
await page.waitForTimeout(400);
console.log("after typing:", JSON.stringify(await where(), null, 1));
await page.screenshot({ path: "palette.png" });
await page.keyboard.press("Escape");
await page.waitForTimeout(300);
console.log("after escape:", JSON.stringify(await where(), null, 1));

// And on a map that is still building: does Ctrl+K do what the reader expects?
await page.getByRole("button", { name: /Back to the launchpad/ }).click();
await page
  .getByRole("button", { name: new RegExp(SENTENCE.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")) })
  .first()
  .click();
await page.locator(".skeleton-tile").first().waitFor();
await page.locator(".react-flow__node").first().click();
await page.keyboard.press("Control+k");
await page.waitForTimeout(500);
console.log(
  "Ctrl+K on a map that is building:",
  await page.evaluate(() => ({
    palette: document.querySelectorAll(".palette").length,
    sheet: document.querySelectorAll(".shortcuts, .sheet, [class*=shortcut]").length,
    what: document.querySelector(".shortcuts, .sheet, [class*=shortcut]")?.className ?? null,
  })),
);
console.log("console:", console_.filter((l) => /error|pageerror/i.test(l)).slice(0, 6));
await browser.close();

