import { open, APP, SENTENCE } from "./lib.mjs";
import { readFileSync } from "node:fs";

const N = Number(process.argv[2] ?? 6);
const whole = readFileSync("stream.txt", "utf8");
const blocks = whole.split(/\n\n/).filter((b) => b.trim() !== "");
const body = blocks.slice(0, N).map((b) => `${b}\n\n`).join("");

const { browser, page, console_ } = await open();
const asked = [];
page.on("request", (r) => {
  if (r.url().includes("/transcript")) asked.push(r.url());
});
await page.route("**/api/generate", async (route) => {
  await route.fulfill({ status: 200, headers: { "content-type": "text/event-stream" }, body });
});
await page.goto(APP);
await page
  .getByRole("button", { name: new RegExp(SENTENCE.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")) })
  .first()
  .click();
await page.locator(".done-line").waitFor();
await page.waitForTimeout(2000);

console.log(
  JSON.stringify(
    {
      N,
      transcriptAsked: asked,
      // Anything at all that would open the panel on the run.
      receiptOpen: await page.locator(".receipt-strip__open").count(),
      refusalRows: await page.locator(".refusal-strip__open").count(),
      generationPanel: await page.locator(".inspector__transcript").count(),
      panelHeadings: await page.evaluate(() =>
        [...document.querySelectorAll(".dock h3, .dock h2, .inspector__claim")].map((h) => h.textContent),
      ),
      everyButtonInTheDock: await page.evaluate(() =>
        [...document.querySelectorAll(".dock button")].map((b) => b.textContent.trim().slice(0, 48)),
      ),
    },
    null,
    1,
  ),
);
await page.screenshot({ path: `working-${N}.png` });
console.log("console:", console_.filter((l) => /error|pageerror/i.test(l)).slice(0, 6));
await browser.close();

