cd /private/tmp/claude-501/-Users-kentgang-git3-katalyst/ef0fe818-4a51-417f-a20d-5479dc442258/scratchpad/review-growth-2 && cat > instant.mjs <<'EOF'
import { open, APP, SENTENCE } from "./lib.mjs";
import { readFileSync } from "node:fs";
const whole = readFileSync("stream.txt", "utf8");
const { browser, page } = await open();
await page.route("**/api/generate", async (route) => {
  await route.fulfill({ status: 200, headers: { "content-type": "text/event-stream" }, body: whole });
});
await page.goto(APP);
await page.evaluate(() => {
  window.rec = { claimsWentOn: [], mostRect: 0, rectBefore: false, whenNumbers: {claims:0,numbers:0} };
  const look = () => {
    const held = document.querySelectorAll(".skeleton-tile").length;
    const claims = document.querySelectorAll(".tile").length;
    const numbers = document.querySelectorAll('.belief-chip[data-reading="number"]').length;
    if (held > 0 && claims === 0) window.rec.rectBefore = true;
    window.rec.mostRect = Math.max(window.rec.mostRect, held);
    const r = window.rec.claimsWentOn;
    if (r[r.length-1] !== claims) r.push(claims);
    if (numbers > 0 && window.rec.whenNumbers.numbers === 0) window.rec.whenNumbers = {claims, numbers};
  };
  new MutationObserver(look).observe(document.body, { subtree:true, childList:true, attributes:true });
  look();
});
await page.getByRole("button", { name: new RegExp(SENTENCE.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")) }).first().click();
await page.locator(".done-line").waitFor({ timeout: 60000 });
await page.waitForTimeout(2500);
console.log(JSON.stringify(await page.evaluate(() => window.rec), null, 1));
await browser.close();
EOF
