input.command:
cd /private/tmp/claude-501/-Users-kentgang-git3-katalyst/ef0fe818-4a51-417f-a20d-5479dc442258/scratchpad/review-growth-2 && cat > resize.mjs <<'EOF'
import { open, APP, SENTENCE } from "./lib.mjs";
const { browser, page } = await open();
await page.goto(APP);
await page.getByRole("button", { name: new RegExp(SENTENCE.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")) }).first().click();
await page.locator(".receipt-strip").first().waitFor({ timeout: 300000 });
await page.locator(".done-line").waitFor();
await page.waitForTimeout(1500);
const read = () => page.evaluate(() => {
  const canvas = document.querySelector(".canvas");
  const room = canvas.getBoundingClientRect();
  const boxes = [...document.querySelectorAll(".react-flow__node")].map(n => n.getBoundingClientRect());
  const said = { left: canvas.dataset.moreLeft, right: canvas.dataset.moreRight, above: canvas.dataset.moreAbove, below: canvas.dataset.moreBelow };
  const truly = { left: boxes.some(b=>b.left<room.left-1)?"yes":"no", right: boxes.some(b=>b.right>room.right+1)?"yes":"no", above: boxes.some(b=>b.top<room.top-1)?"yes":"no", below: boxes.some(b=>b.bottom>room.bottom+1)?"yes":"no" };
  const frame = document.querySelector(".dock-frame"); const dock = document.querySelector(".dock");
  return { said, truly, panelSaid: {above: frame.dataset.moreAbove, below: frame.dataset.moreBelow},
           panelTruly: {above: dock.scrollTop>1?"yes":"no", below: dock.scrollTop+dock.clientHeight<dock.scrollHeight-1?"yes":"no"} };
});
const show = async (what) => {
  const r = await read();
  const stageOK = JSON.stringify(r.said)===JSON.stringify(r.truly);
  const panelOK = JSON.stringify(r.panelSaid)===JSON.stringify(r.panelTruly);
  console.log(what.padEnd(28), JSON.stringify(r.said), JSON.stringify(r.truly), stageOK?"stage OK":"STAGE WRONG", "|", JSON.stringify(r.panelSaid), JSON.stringify(r.panelTruly), panelOK?"panel OK":"PANEL WRONG");
};
await show("1600x1000");
for (const [w,h] of [[900,620],[2000,1400],[1200,700],[1600,1000],[700,500]]) {
  await page.setViewportSize({width:w,height:h});
  await page.waitForTimeout(900);
  await show(`${w}x${h}`);
}
await page.screenshot({ path: "resized.png" });
console.log("loops:", await page.evaluate(() => window.__loops ?? []));
await browser.close();
EOF
node resize.mjs 2>&1 | tail -12

